 std::vector<uint32_t> data(primes.size()*96);
 for(unsigned pi=0;pi<primes.size();++pi){const uint64_t p=primes[pi];
  for(unsigned j=0;j<48;++j){const uint64_t n=p*classes[j];
   if(index[n%30]<0||p>40000)throw std::runtime_error("Event210 prime table/domain invalid");
   data[pi*96+j]=uint32_t((n/30)*8+unsigned(index[n%30]));
   data[pi*96+j+48]=data[pi*96+j]+uint32_t(56*p);
  }
 }return data;
}
inline cudaError_t upload(const std::vector<uint64_t>& primes,uint32_t** allocation){
 const auto data=makePrefix(primes);cudaError_t e=cudaMalloc(allocation,data.size()*sizeof(uint32_t));if(e!=cudaSuccess)return e;
 e=cudaMemcpy(*allocation,data.data(),data.size()*sizeof(uint32_t),cudaMemcpyHostToDevice);if(e!=cudaSuccess)return e;
 return cudaMemcpyToSymbol(prefix,allocation,sizeof(*allocation));
}
